sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.quick-access {
    padding: 65px 7%;
    background: #ffffff;
    font-family: Arial, sans-serif;
}

.quick-heading {
    text-align: center;
    margin-bottom: 38px;
}

.quick-heading > span {
    color: #a8895e;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
}

.quick-heading h2 {
    color: #1f3a30;
    font-family: Georgia, serif;
    font-size: 36px;
    margin: 10px 0;
}

.quick-heading p {
    color: #6f756f;
    font-size: 14px;
}

.quick-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px;
}

.quick-card {
    display: block;
    padding: 32px 28px;
    background: #faf6ef;
    border: 1px solid #e7e1d4;
    text-decoration: none !important;
    transition: transform 0.25s, box-shadow 0.25s;
}

.quick-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 12px 25px rgba(31, 58, 48, 0.10);
}

.quick-icon {
    width: 52px;
    height: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e8eee9;
    color: #1f3a30;
    font-size: 21px;
    margin-bottom: 22px;
}

.quick-card h3 {
    color: #1f3a30;
    font-family: Georgia, serif;
    font-size: 23px;
    margin: 0 0 12px;
}

.quick-card p {
    color: #6f756f;
    font-size: 13px;
    line-height: 1.7;
    min-height: 44px;
}

.quick-card > span {
    display: inline-block;
    margin-top: 20px;
    color: #a8895e;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
}

.quick-card:hover > span {
    color: #1f3a30;
}

@media (max-width: 767px) {
    .quick-grid {
        grid-template-columns: 1fr;
    }

    .quick-access {
        padding: 45px 20px;
    }
}
